put('integration','rst31-hygiene2-noro-source-scope',{'title':'लगभग आठ-दसवाँ किसका है, न बदलें','text':'पाठ का लगभग80% खाद्य कर्मियों के80% संक्रमित होने का अर्थ नहीं। मंत्रालय की10नवंबर2017सूचना में भी ऐसी बात है; दायरा नोरोवायरस खाद्य विषाक्तता और कर्मचारियों से भोजन का संदूषण है। पाठ का मूल आँकड़ा निश्चित नहीं; नवीनतम सभी विषाक्तता या किसी दुकान की दर न बनाएँ। काम से पहले स्वास्थ्य और सही हाथ धोने जैसी रोकथाम जारी रखने का अर्थ समझाएँ।'},{'title':'প্রায় আট-দশমাংশের বিষয় বদলাবেন না','text':'পাঠের প্রায়80% মানে খাদ্যকর্মীর80% সংক্রমিত নয়। মন্ত্রণালয়ের10নভেম্বর2017বিজ্ঞপ্তিতেও অনুরূপ কথা; বিষয় নোরোভাইরাস খাদ্যবিষক্রিয়া ও কর্মীর মাধ্যমে খাবার দূষণ। পাঠের মূল সমষ্টি নিশ্চিত নয়; সর্বশেষ সব বিষক্রিয়া বা এক দোকানের হার নয়। কাজের আগে স্বাস্থ্য ও সঠিক হাত ধোয়ার মতো নিয়ন্ত্রণ চালানোর অর্থ বোঝান।'})
put('integration','rst31-hygiene2-link-noro-2017',{'title':'2017की सूचना आधिकारिक पृष्ठ पर देखें','text':'दायरा और समय सही रखने के लिए मंत्रालय की उस समय की सूचना देखें।'},{'title':'2017বিজ্ঞপ্তি সরকারি পাতায় দেখুন','text':'বিষয়-সময় ধরে বোঝাতে মন্ত্রণালয়ের তৎকালীন বিজ্ঞপ্তি দেখুন।'})
Q('rst31-hygiene2-q049',['मंत्रालय की2017सूचना का लगभग आठ-दसवाँ कैसे समझें?','अनुपात का दायरा और स्रोत का समय अलग करें।',['उस जाँच के लगभग आठ-दसवाँ कर्मचारी संक्रमित थे','2026में हर दुकान की नोरोवायरस विषाक्तता हमेशा आठ-दसवाँ है','सभी खाद्य विषाक्तता में आठ-दसवाँ नोरोवायरस है','नोरोवायरस विषाक्तता में कर्मचारी से भोजन का संदूषण अधिक होने का वर्णन'],'दायरा नोरोवायरस विषाक्तता और कर्मचारी से संदूषण है; कर्मचारी संक्रमण, सभी विषाक्तता का कारण-अनुपात या हर वर्तमान दुकान की गारंटी नहीं।',['कारण-मार्ग को कर्मचारी संक्रमण बनाया है।','2017को2026की स्थिर दुकान-दर बनाया है।','नोरोवायरस के कारण को समूची विषाक्तता में फैलाया है।','सूचना का दायरा-मार्ग रखकर स्वास्थ्य और हाथ धोने से जोड़ सकते हैं।']],['মন্ত্রণালয়ের2017বিজ্ঞপ্তির প্রায় আট-দশমাংশ কীভাবে বুঝবেন?','অনুপাতের বিষয় ও উৎসের সময় আলাদা।',['সেই পরীক্ষায় আট-দশমাংশ কর্মী সংক্রমিত','2026এ সব দোকানের নোরোভাইরাস বিষক্রিয়া আট-দশমাংশই','সব বিষক্রিয়ার আট-দশমাংশ নোরোভাইরাস','নোরোভাইরাস বিষক্রিয়ায় কর্মীর মাধ্যমে খাবার দূষণ বেশি বলা'],'বিষয় নোরোভাইরাস বিষক্রিয়া ও কর্মীর মাধ্যমে দূষণ, কর্মীর সংক্রমণ বা সব বিষক্রিয়ার অনুপাত বা বর্তমান দোকানের নিশ্চয়তা নয়।',['কারণের পথকে কর্মীর সংক্রমণ করেছে।','2017কে2026এর স্থির দোকানহার করেছে।','নোরোভাইরাসের কারণকে সব বিষক্রিয়ায় বাড়িয়েছে।','বিষয়-পথ রেখে স্বাস্থ্য-হাত ধোয়ায় যুক্ত করে।']])
Q('rst31-integration-q001',['पाठ के मछली-चित्र में गलफड़े के ढक्कन के पीछे, पेट की आगे और पेट की पीछे के पंखों का क्रम क्या है?','छाती, पेट और गुदा-पंख को सामान्य चित्र के स्थान से जोड़ें।',['छाती, गुदा, पेट','गुदा, पेट, छाती','छाती, पेट, गुदा','पेट, छाती, गुदा'],'सामान्य चित्र में छाती गलफड़े के पीछे, पेट आगे और गुदा पेट के पीछे है। प्रजाति का भेद छोड़कर हर मछली पर निश्चित न करें।',['पेट के आगे-पीछे के नाम उलटे हैं।','गलफड़े के पीछे और पेट के पीछे के नाम उलटे हैं।','तीनों नाम-स्थान चित्र से मिलते हैं।','छाती और पेट के आगे का पंख उलटा है।']],['পাঠের মাছে ফুলকার ঢাকনার পেছন, পেটের সামনে ও পেছনের পাখনার ক্রম কী?','বক্ষ, শ্রোণি ও পায়ুপাখনা সাধারণ ছবির স্থানে মেলানো।',['বক্ষ, পায়ু, শ্রোণি','পায়ু, শ্রোণি, বক্ষ','বক্ষ, শ্রোণি, পায়ু','শ্রোণি, বক্ষ, পায়ু'],'সাধারণ ছবিতে বক্ষ ফুলকার পেছন, শ্রোণি পেটের সামনে, পায়ু পেছনে। প্রজাতির গঠনভেদ বাদ দিয়ে সব মাছে নয়।',['সামনে-পেছনের নাম উল্টো।','ফুলকার পেছন-পেটের পেছনের নাম উল্টো।','তিন নাম-স্থান মেলে।','বক্ষ ও সামনের শ্রোণি উল্টো।']])
Q('rst31-integration-q002',['प्रबंधक ने केवल महत्वपूर्ण गर्म करने का चरण बनाया और सफाई-हाथ धोना लोगों पर छोड़ा। सुधार क्या है?','सामान्य और महत्वपूर्ण चरण के प्रबंधन को जोड़कर कर्मचारियों को विधि बताएँ।',['योजना केवल प्रभारी पढ़े, कर्मचारियों को न दें और केवल परिणाम देखें','गर्मी के अभिलेख हैं, सफाई-हाथ की योजना छोड़ें','सामान्य स्वच्छता भी जोड़ें; कर्मचारी काम और असामान्यता की सूचना समझा सकता है जाँचें','केवल सफाई योजना, गर्म करना अनुभव पर छोड़ें'],'HACCPअनुसार सामान्य और महत्वपूर्ण चरण साथ लें, कर्मचारियों को बताकर लागू कराएँ; कागज मात्र पर्याप्त नहीं।',['लागू करने वालों को जानकारी नहीं।','महत्वपूर्ण चरण से सामान्य स्वच्छता नहीं छोड़ सकते।','दो प्रबंधन और समझ-कार्यान्वयन जाँचता है।','सामान्य से महत्वपूर्ण चरण नहीं बदल सकते।']],['ম্যানেজার শুধু গুরুত্বপূর্ণ উত্তাপ পরিকল্পনা করে পরিষ্কার-হাত ধোয়া কর্মীর ওপর ছেড়েছেন। উন্নতি কী?','সাধারণ-গুরুত্বপূর্ণ নিয়ন্ত্রণ মিলিয়ে কর্মীদের পদ্ধতি জানানো।',['শুধু দায়িত্বপ্রাপ্ত পড়ে কর্মীকে নয়, ফল দেখা','উত্তাপের নথিতে পরিষ্কার-হাতের পরিকল্পনা বাদ','সাধারণ স্বাস্থ্যবিধিও যোগ করে কর্মী কাজ-অস্বাভাবিকতার খবর বোঝাতে পারেন কি না দেখা','শুধু পরিষ্কার পরিকল্পনা, উত্তাপ অভিজ্ঞতায়'],'HACCPতে সাধারণ-গুরুত্বপূর্ণ একসঙ্গে জানিয়ে বাস্তবায়ন, কাগজ যথেষ্ট নয়।',['বাস্তবায়নকারীকে জানানো নেই।','গুরুত্বপূর্ণ থাকলেও সাধারণ বাদ নয়।','দুই নিয়ন্ত্রণ ও বোঝা-বাস্তবায়ন দেখছে।','সাধারণে গুরুত্বপূর্ণ বদলায় না।']])
Q('rst31-integration-q003',['स्वैच्छिक वापसी शुरू हुई। कहा स्वैच्छिक है तो सूचना जरूरी नहीं। सही क्या है?','वापसी शुरू करने और सूचना की जरूरत अलग समझें।',['स्वैच्छिक हो तो उत्पाद-कारण बिना सूचना नहीं','वापसी और सूचना अलग करके प्रभारी-स्वास्थ्य केंद्र से लागू शर्त देखें','पुष्टि तक संदिग्ध भोजन सामान्य परोसें','सभी लौटाना समान और कारण-खाद्य के अभिलेख छोड़ें'],'वापसी का निर्णय और कानूनी सूचना-दायरा अलग हैं। अपवाद, उत्पाद, कारण और कार्रवाई दर्ज करें; केवल स्वैच्छिक कहकर नहीं।',['नाम मात्र सूचना छोड़ने का आधार नहीं।','निर्णय-सूचना अलग और व्यक्तिगत शर्त देखी है।','पुष्टि में भी नुकसान रोकें; परोसना जारी का आधार नहीं।','कारण-वस्तु संपर्क के लिए जरूरी; हर वापसी समान नहीं।']],['স্বেচ্ছা প্রত্যাহার শুরু। বলা হলো স্বেচ্ছা হলে বিজ্ঞপ্তি নয়। সঠিক কী?','শুরু করার সিদ্ধান্ত ও বিজ্ঞপ্তির দরকার আলাদা।',['স্বেচ্ছা হলে পণ্য-কারণ নির্বিশেষে নয়','প্রত্যাহার-বিজ্ঞপ্তি আলাদা করে দায়িত্বপ্রাপ্ত-স্বাস্থ্যকেন্দ্রে শর্ত দেখা','যাচাই পর্যন্ত সন্দেহের খাবার স্বাভাবিক দেওয়া','সব ফেরত এক, কারণ-পণ্যের নথি বাদ'],'সিদ্ধান্ত ও আইনি আওতা আলাদা; ব্যতিক্রম, পণ্য-কারণ-ব্যবস্থা লিখুন, স্বেচ্ছা নামেই নয়।',['শুধু নামেই বিজ্ঞপ্তি বাদ নয়।','সিদ্ধান্ত-বিজ্ঞপ্তি ও প্রযোজ্য শর্ত দেখা।','যাচাইতেও ক্ষতি রোধ দরকার, পরিবেশন নয়।','কারণ-বিষয় যোগাযোগে দরকার, সব ফেরত এক নয়।']])
Q('rst31-integration-q004',['ব্যবসায়ী'.replace('ব্যবসায়ী','व्यवसायी ने स्वच्छता प्रभारी नियुक्त किया। सही भूमिका क्या है?'),'प्रभारी के काम और व्यवसायी के निर्देश-जिम्मेदारी का संबंध समझें।',['प्रभारी व्यवसायी के निर्देश में स्वच्छता करे और समस्याएँ साझा करे','नियुक्ति के बाद व्यवसायी को संबंध नहीं','निर्देश हो तो प्रभारी को काम नहीं','समस्या जानकर भी व्यवसायी को न बताएँ'],'प्रभारी निर्देश से काम करता है; नियुक्ति व्यवसायी की जिम्मेदारी खत्म नहीं करती। राय और समस्या साझा करें।',['काम और व्यवसायी की भूमिका दोनों हैं।','नियुक्ति के बाद भी व्यवसायी अलग नहीं हो सकता।','निर्देश काम न करने का अर्थ नहीं।','साझा बिना सुधार नहीं।']],['ব্যবসায়ী স্বাস্থ্যবিধির দায়িত্বপ্রাপ্ত রেখেছেন। সঠিক ভূমিকা কী?','দায়িত্বপ্রাপ্তের কাজ ও ব্যবসায়ীর নির্দেশ-দায় আলাদা।',['নির্দেশে স্বাস্থ্যবিধি করে সমস্যা ভাগ','নিয়োগে ব্যবসায়ীর সম্পর্ক নেই','নির্দেশ হলে দায়িত্বপ্রাপ্তের কাজ নেই','সমস্যা জেনেও জানাবেন না'],'নির্দেশে কাজ হলেও ব্যবসায়ীর দায় শেষ নয়; মত-সমস্যা ভাগ করুন।',['কাজ-ব্যবসায়ীর ভূমিকা দুটো।','নিয়োগেও ব্যবসায়ী সরবেন না।','নির্দেশ মানে কাজ বাদ নয়।','ভাগ ছাড়া উন্নতি নয়।']])
Q('rst31-integration-q005',['रसोइया घर में परिवार की उल्टी साफ करता है। संक्रमण रोकने की सही सोच क्या है?','दैनिक जीवन की संक्रमण-रोकथाम और उल्टी आदि में आत्म-सुरक्षा जाँचें।',['दस्ताने से संक्रमण नहीं, बाकी जाँच नहीं','घर का संक्रमण काम से असंबंधित, नंगे हाथ','घर में भी सावधानी; एक-बार मास्क, दस्ताने और एप्रन से बचें','गंदे काम के कपड़े पहनकर घरेलू संक्रमण रोकें'],'कर्मचारी घर-दैनिक जीवन में भी संक्रमण देखें। मल/उल्टी में एक-बार मास्क-दस्ताने-एप्रन मूल बचाव हैं; वास्तविक विधि और रसायन अलग जाँचें।',['दस्ताने अकेले पूर्ण सुरक्षा नहीं।','घरेलू संक्रमण से कर्मचारी संदूषण-स्रोत हो सकता है।','घर का बचाव और पाठ की आत्म-सुरक्षा जुड़े हैं।','गंदे कपड़े रोकथाम नहीं, फैलाव का खतरा हैं।']],['রাঁধুনি বাড়িতে পরিবারের বমি পরিষ্কার করছেন। সংক্রমণ রোধে কী ঠিক?','দৈনন্দিন সংক্রমণ রোধ ও বমি ইত্যাদিতে আত্মরক্ষা দেখা।',['দস্তানায় সংক্রমণ নেই, আর কিছু নয়','বাড়ির সংক্রমণ কাজে নয়, খালি হাতে','বাড়িতেও সতর্ক; একবারের মাস্ক-দস্তানা-এপ্রনে রক্ষা','নোংরা কাজের পোশাকে বাড়ির সংক্রমণ রোধ'],'ঘর-জীবনেও সংক্রমণ দেখুন। মল-বমিতে একবারের মাস্ক-দস্তানা-এপ্রন মূল রক্ষা, প্রক্রিয়া-রাসায়নিক আলাদা।',['দস্তানা একাই শূন্য সম্ভাবনা নয়।','বাড়ির সংক্রমণে কর্মী দূষণের উৎস হতে পারেন।','বাড়ির রোধ ও পাঠের আত্মরক্ষা যুক্ত।','নোংরা পোশাক প্রতিরোধ নয়, ছড়ানোর ঝুঁকি।']])
Q('rst31-integration-q006',['ग्राहक टेकअवे के भंडारण और खाने का तरीका पूछता है। क्या उचित है?','पुष्ट खाद्य और सुरक्षित पकाने-भंडारण की जानकारी दें।',['ग्राहक की जिम्मेदारी है, पुष्ट जानकारी भी न दें','पुष्ट भंडारण-पकाने की शर्त बताएँ, अस्पष्ट बात जाँचकर उत्तर दें','बिना जाँचे पूरी सुरक्षा कहें','हर भोजन अगले दिन तक कमरे में सुरक्षित बताएँ'],'सुरक्षित खाने के लिए पुष्ट जानकारी दें, उत्पाद की शर्त जाँचें; आधारहीन ताप-समय सभी के लिए न गढ़ें।',['पुष्ट सुरक्षित जानकारी नुकसान रोकती है।','पुष्ट जानकारी और भोजन की शर्त बताई है।','अपुष्ट गारंटी सही निर्णय रोकती है।','भोजन-शर्त अलग, कमरे में समान गारंटी नहीं।']],['অতিথি বহনযোগ্য খাবারের সংরক্ষণ-খাওয়া জিজ্ঞাসা করেন। কী ঠিক?','যাচাইকৃত খাদ্য ও নিরাপদ রান্না-সংরক্ষণ জানানো।',['অতিথির দায় বলে জানা তথ্যও নয়','জানা শর্ত-পদ্ধতি বলা, অজানা দেখে উত্তর','না জেনেও সম্পূর্ণ নিরাপদ','সব খাবার পরদিন পর্যন্ত ঘরে নিরাপদ'],'নিরাপদ খেতে জানা তথ্য দিন, পণ্যভেদে দেখুন; ভিত্তিহীন তাপ-মেয়াদ একভাবে বানাবেন না।',['জানা নিরাপদ তথ্য ক্ষতি রোধে সাহায্য।','জানা তথ্য ও পণ্যের শর্ত বলা।','অযাচাইকৃত নিশ্চয়তা সিদ্ধান্তে বাধা।','খাদ্য-শর্ত আলাদা, ঘরে এক নিশ্চয়তা নয়।']])
Q('rst31-integration-q007',['नया कर्मचारी कहता सत्कार की भावना हो तो गति का अभ्यास नहीं चाहिए। सही सलाह क्या है?','परवाह को ठोस काम और दोहराए अभ्यास से जोड़ें।',['परवाह को साफ, दयालु और शिष्ट काम में बार-बार अभ्यास करें','सबसे वही काम, इच्छा पूछना नहीं','भावना हो तो सफाई-शिष्टता नहीं देखना','मना करने पर भी वही मदद जारी'],'सत्कार परवाह को कार्य में दिखाना है। मूल गति सीखकर दोहराएँ और स्थिति-इच्छा पूछें; राष्ट्रीयता या समूह को एक गुण नहीं देते।',['भावना और काम-कौशल साथ हैं।','मूल काम के बाद भी इच्छा पूछें।','भावना से स्वच्छता-शिष्टता नहीं छोड़ें।','इच्छा अनदेखी मदद परवाह नहीं।']],['নতুন কর্মী বললেন আতিথ্যের মন থাকলে কাজের অনুশীলন নয়। সঠিক পরামর্শ?','যত্নকে নির্দিষ্ট কাজ ও পুনরাবৃত্তিতে যুক্ত।',['যত্নকে পরিষ্কার-সদয়-ভদ্র কাজে বারবার অনুশীলন','সবাইকে এক কাজ, ইচ্ছা নয়','মন থাকলে পরিষ্কার-ভদ্রতা নয়','না বললেও একই সাহায্য'],'আতিথ্য যত্নকে কাজে দেখানো; মূল কাজ শিখে পুনরাবৃত্তি ও অবস্থা-ইচ্ছা দেখা। জাতীয়তা-গোষ্ঠীকে এক বৈশিষ্ট্য নয়।',['মন-কাজ-দক্ষতা যুক্ত।','মূল কাজেও ইচ্ছা জানতে হয়।','মনে পরিচ্ছন্নতা-ভদ্রতা বাদ নয়।','ইচ্ছা না মানা যত্ন নয়।']])
Q('rst31-integration-q008',['कई छोटी प्रतीक्षा और कम स्पष्टीकरण के बाद ग्राहक नाराज हुआ। सही समझ और कार्य क्या है?','छोटी असंतुष्टियाँ जुड़ सकती हैं; जल्दी स्थिति सुनें।',['केवल अंतिम घटना कारण, पहले न सुनें','छोटी बातें जुड़ी हों सकती हैं; असंतुष्टि विनम्रता से सुनें','हर प्रतीक्षा छोटी हो तो जुड़ना असंभव','सेवा बिना जाँचे केवल स्वभाव से निर्णय'],'शिकायत से पहले कई छोटी असंतुष्टियाँ जुड़ सकती हैं। एक कारण न तय करें; ग्राहक की बात से स्थिति जाँचें।',['केवल अंतिम जरूरी नहीं; पिछला देखें।','जुड़ना संभावना मानकर सुनते हैं।','छोटी प्रतीक्षा भी कम व्याख्या से बड़ी हो सकती है।','स्वभाव मात्र से सेवा की समस्या नहीं मिलेगी।']],['কয়েক ছোট অপেক্ষা ও কম ব্যাখ্যার পর অতিথি তীব্র অসন্তুষ্ট। কী বোঝা-ব্যবস্থা ঠিক?','ছোট অসন্তুষ্টি জমা বোঝা ও আগে শোনা।',['শুধু শেষ ঘটনা কারণ, আগের নয়','ছোট অসন্তুষ্টি জমতে পারে, কী ছিল ভদ্রভাবে শোনা','অপেক্ষা ছোট হলে জমে না','সেবা না দেখে শুধু চরিত্র'],'অভিযোগের আগে ছোট অসন্তুষ্টি জমতে পারে। এক কারণ নয়, কথা শুনে যাচাই।',['শুধু শেষ নয়, আগেরও দেখুন।','জমাকে সম্ভাবনা ধরে শোনা।','কম ব্যাখ্যার সঙ্গে ছোট অপেক্ষাও বড় হয়।','চরিত্রে বিচার করলে সেবার সমস্যা অজানা।']])
